307	import io.javalin.http.Context;
308	
309	import java.time.LocalDate;
310	import java.time.format.DateTimeParseException;
311	import java.util.HashMap;
312	import java.util.Map;
313	
314	public class ReservationController {
315	    private final ReservationService reservationService;
316	
317	    public ReservationController(ReservationService reservationService) {
318	        this.reservationService = reservationService;
319	    }
320	
321	    public void createReservation(Context ctx) {
322	        try {
323	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
324	
325	            String roomNumber = (String) body.get("roomNumber");
326	            String guestName = (String) body.get("guestName");
327	            String guestEmail = (String) body.get("guestEmail");
328	            String guestCpf = (String) body.get("guestCpf");
329	            String checkInStr = (String) body.get("checkIn");
330	            String checkOutStr = (String) body.get("checkOut");
331	            Integer guests = ((Number) body.get("guests")).intValue();
332	            String ratePlanStr = (String) body.get("ratePlan");
333	
334	            if (roomNumber == null || guestName == null || guestEmail == null ||
335	                guestCpf == null || checkInStr == null || checkOutStr == null ||
336	                guests == null || ratePlanStr == null) {
337	                ctx.status(400).json(Map.of(
338	                    "error", "INVALID_REQUEST",
339	                    "message", "Missing required fields"
340	                ));
341	                return;
342	            }
343	
344	            if (guests < 1) {
345	                ctx.status(400).json(Map.of(
346	                    "error", "INVALID_REQUEST",
347	                    "message", "At least one guest is required"
348	                ));
349	                return;
350	            }
351	
352	            LocalDate checkIn = LocalDate.parse(checkInStr);
353	            LocalDate checkOut = LocalDate.parse(checkOutStr);
354	
355	            if (!checkOut.isAfter(checkIn)) {
356	                ctx.status(400).json(Map.of(
357	                    "error", "INVALID_REQUEST",
358	                    "message", "Check-out must be after check-in"
359	                ));
360	                return;
361	            }
362	
363	            RatePlan ratePlan = RatePlan.valueOf(ratePlanStr);
364	
365	            Reservation reservation = reservationService.createReservation(
366	                roomNumber, guestName, guestEmail, guestCpf,
367	                checkIn, checkOut, guests, ratePlan
368	            );
369	
370	            ctx.status(201).json(toMap(reservation));
371	
372	        } catch (DateTimeParseException e) {
373	            ctx.status(400).json(Map.of(
374	                "error", "INVALID_REQUEST",
375	                "message", "Invalid date format"
376	            ));
377	        } catch (IllegalArgumentException e) {
378	            ctx.status(400).json(Map.of(
379	                "error", "INVALID_REQUEST",
380	                "message", "Invalid rate plan"
381	            ));
382	        } catch (ReservationService.RoomNotFoundException e) {
383	            ctx.status(404).json(Map.of(
384	                "error", "ROOM_NOT_FOUND",
385	                "message", "Room not found"
386	            ));
387	        } catch (ReservationService.CapacityExceededException e) {
388	            ctx.status(422).json(Map.of(
389	                "error", "CAPACITY_EXCEEDED",
390	                "message", "Number of guests exceeds room capacity"
391	            ));
392	        } catch (ReservationService.RoomUnavailableException e) {
393	            ctx.status(409).json(Map.of(
394	                "error", "ROOM_UNAVAILABLE",
395	                "message", "Room is not available for the selected dates"
396	            ));
397	        } catch (Exception e) {
398	            ctx.status(400).json(Map.of(
399	                "error", "INVALID_REQUEST",
400	                "message", e.getMessage()
401	            ));
402	        }
403	    }
404	
405	    public void getReservation(Context ctx) {
406	        try {
407	            Long id = Long.parseLong(ctx.pathParam("id"));
408	            Reservation reservation = reservationService.getReservation(id);
409	            ctx.json(toMap(reservation));
410	        } catch (ReservationService.ReservationNotFoundException e) {
411	            ctx.status(404).json(Map.of(
412	                "error", "RESERVATION_NOT_FOUND",
413	                "message", "Reservation not found"
414	            ));
415	        }
416	    }
417	
418	    public void confirmReservation(Context ctx) {
419	        try {
420	            Long id = Long.parseLong(ctx.pathParam("id"));
421	            Reservation reservation = reservationService.confirmReservation(id);
422	            ctx.json(toMap(reservation));
423	        } catch (ReservationService.ReservationNotFoundException e) {
424	            ctx.status(404).json(Map.of(
425	                "error", "RESERVATION_NOT_FOUND",
426	                "message", "Reservation not found"
427	            ));
428	        } catch (ReservationService.OperationNotAllowedException e) {
429	            ctx.status(409).json(Map.of(
430	                "error", "OPERATION_NOT_ALLOWED",
431	                "message", "Cannot confirm reservation in current status"
432	            ));
433	        }
434	    }
435	
436	    public void cancelReservation(Context ctx) {
437	        try {
438	            Long id = Long.parseLong(ctx.pathParam("id"));
439	            Reservation reservation = reservationService.cancelReservation(id);
440	            ctx.json(toMap(reservation));
441	        } catch (ReservationService.ReservationNotFoundException e) {
442	            ctx.status(404).json(Map.of(
443	                "error", "RESERVATION_NOT_FOUND",
444	                "message", "Reservation not found"
445	            ));
446	        } catch (ReservationService.OperationNotAllowedException e) {
447	            ctx.status(409).json(Map.of(
448	                "error", "OPERATION_NOT_ALLOWED",
449	                "message", "Cannot cancel reservation in current status"
450	            ));
451	        }
452	    }
453	
454	    public void checkIn(Context ctx) {
455	        try {
456	            Long id = Long.parseLong(ctx.pathParam("id"));
457	            Reservation reservation = reservationService.checkIn(id);
458	            ctx.json(toMap(reservation));
459	        } catch (ReservationService.ReservationNotFoundException e) {
460	            ctx.status(404).json(Map.of(
461	                "error", "RESERVATION_NOT_FOUND",
462	                "message", "Reservation not found"
463	            ));
464	        } catch (ReservationService.OperationNotAllowedException e) {
465	            ctx.status(409).json(Map.of(
466	                "error", "OPERATION_NOT_ALLOWED",
467	                "message", "Cannot check-in reservation in current status"
468	            ));
469	        }
470	    }
471	
472	    public void checkOut(Context ctx) {
473	        try {
474	            Long id = Long.parseLong(ctx.pathParam("id"));
475	            Reservation reservation = reservationService.checkOut(id);
476	
477	            Map<String, Object> receipt = new HashMap<>();
478	            receipt.put("title", "Comprovante de reserva");
479	            receipt.put("reservationId", reservation.getId());
480	            receipt.put("guestName", reservation.getGuestName());
481	            receipt.put("guestCpf", reservation.getGuestCpf());
482	            receipt.put("roomNumber", reservation.getRoomNumber());
483	            receipt.put("roomType", getRoomType(reservation.getRoomNumber()));
484	            receipt.put("checkIn", reservation.getCheckIn().toString());
485	            receipt.put("checkOut", reservation.getCheckOut().toString());
486	            receipt.put("nights", reservation.getNights());
487	            receipt.put("subtotal", reservation.getSubtotal());
488	            receipt.put("discount", reservation.getDiscount());
489	            receipt.put("total", reservation.getTotal());
490	
491	            ctx.json(receipt);
492	        } catch (ReservationService.ReservationNotFoundException e) {
493	            ctx.status(404).json(Map.of(
494	                "error", "RESERVATION_NOT_FOUND",
495	                "message", "Reservation not found"
496	            ));
497	        } catch (ReservationService.OperationNotAllowedException e) {
498	            ctx.status(409).json(Map.of(
499	                "error", "OPERATION_NOT_ALLOWED",
500	                "message", "Cannot check-out reservation in current status"
501	            ));
502	        }
503	    }
504	
505	    public void getDocument(Context ctx) {
506	        try {
507	            Long id = Long.parseLong(ctx.pathParam("id"));
508	            Reservation reservation = reservationService.getReservation(id);
509	
510	            if (reservation.getAmountPaid().signum() == 0) {
511	                ctx.status(409).json(Map.of(
512	                    "error", "OPERATION_NOT_ALLOWED",
513	                    "message", "No receipt available for unpaid reservation"
514	                ));
515	                return;
516	            }
517	
518	            Map<String, Object> receipt = new HashMap<>();
519	            receipt.put("title", "Comprovante de reserva");
520	            receipt.put("reservationId", reservation.getId());
521	            receipt.put("guestName", reservation.getGuestName());
522	            receipt.put("guestCpf", reservation.getGuestCpf());
523	            receipt.put("roomNumber", reservation.getRoomNumber());
524	            receipt.put("roomType", getRoomType(reservation.getRoomNumber()));
525	            receipt.put("checkIn", reservation.getCheckIn().toString());
526	            receipt.put("checkOut", reservation.getCheckOut().toString());
527	            receipt.put("nights", reservation.getNights());
528	            receipt.put("subtotal", reservation.getSubtotal());
529	            receipt.put("discount", reservation.getDiscount());
530	            receipt.put("total", reservation.getTotal());
531	
532	            ctx.json(receipt);
533	        } catch (ReservationService.ReservationNotFoundException e) {
534	            ctx.status(404).json(Map.of(
535	                "error", "RESERVATION_NOT_FOUND",
536	                "message", "Reservation not found"
537	            ));
538	        }
539	    }
540	
541	    private Map<String, Object> toMap(Reservation r) {
542	        Map<String, Object> map = new HashMap<>();
543	        map.put("id", r.getId());
544	        map.put("roomNumber", r.getRoomNumber());
545	        map.put("guestName", r.getGuestName());
546	        map.put("guestEmail", r.getGuestEmail());
547	        map.put("guestCpf", r.getGuestCpf());
548	        map.put("checkIn", r.getCheckIn().toString());
549	        map.put("checkOut", r.getCheckOut().toString());
550	        map.put("guests", r.getGuests());
551	        map.put("ratePlan", r.getRatePlan().name());
552	        map.put("nights", r.getNights());
553	        map.put("subtotal", r.getSubtotal());
554	        map.put("discount", r.getDiscount());
555	        map.put("total", r.getTotal());
556	        map.put("status", r.getStatus().name());
557	        map.put("amountPaid", r.getAmountPaid());
558	        map.put("refund", r.getRefund());
559	        return map;
560	    }
561	
562	    private String getRoomType(String roomNumber) {
563	        if (roomNumber.startsWith("1")) return "STANDARD";
564	        if (roomNumber.startsWith("2")) return "DELUXE";
565	        return "SUITE";
566	    }
567	}
