 21	import com.pousadamarealta.service.ReservationService;
 22	import io.javalin.Javalin;
 23	import io.javalin.json.JavalinJackson;
 24	
 25	public class Main {
 26	    public static void main(String[] args) {
 27	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 28	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 29	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 30	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 31	
 32	        Database.init(dbUrl, dbUser, dbPassword);
 33	
 34	        RoomRepository roomRepository = new RoomRepository();
 35	        ReservationRepository reservationRepository = new ReservationRepository();
 36	        MessageRepository messageRepository = new MessageRepository();
 37	
 38	        PricingService pricingService = new PricingService();
 39	        NotificationService notificationService = new NotificationService(messageRepository);
 40	        ReportService reportService = new ReportService(reservationRepository);
 41	
 42	        EventPublisher eventPublisher = new EventPublisher();
 43	
 44	        eventPublisher.subscribe(ReservationConfirmedEvent.class,
 45	            new GuestNotificationListener(notificationService));
 46	        eventPublisher.subscribe(ReservationConfirmedEvent.class,
 47	            new HousekeepingNotificationListener(notificationService));
 48	        eventPublisher.subscribe(ReservationConfirmedEvent.class,
 49	            new FinanceNotificationListener(notificationService));
 50	
 51	        eventPublisher.subscribe(ReservationCancelledEvent.class,
 52	            new HousekeepingCancellationListener(notificationService));
 53	        eventPublisher.subscribe(ReservationCancelledEvent.class,
 54	            new FinanceCancellationListener(notificationService));
 55	
 56	        ReservationService reservationService = new ReservationService(
 57	            reservationRepository, roomRepository, pricingService, eventPublisher);
 58	
 59	        RoomController roomController = new RoomController(roomRepository);
 60	        ReservationController reservationController = new ReservationController(reservationService);
 61	        MessageController messageController = new MessageController(messageRepository);
 62	        ReportController reportController = new ReportController(reportService);
 63	
 64	        ObjectMapper objectMapper = new ObjectMapper();
 65	        objectMapper.registerModule(new JavaTimeModule());
 66	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 67	
 68	        Javalin app = Javalin.create(config -> {
 69	            config.jsonMapper(new JavalinJackson(objectMapper, false));
 70	        }).start(port);
 71	
 72	        app.get("/rooms", roomController::getRooms);
 73	
 74	        app.post("/reservations", reservationController::createReservation);
 75	        app.get("/reservations/{id}", reservationController::getReservation);
 76	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 77	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 78	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 79	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 80	        app.get("/reservations/{id}/document", reservationController::getDocument);
 81	
 82	        app.get("/messages", messageController::getMessages);
 83	
 84	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 85	        app.get("/reports/revenue", reportController::getRevenueReport);
 86	
 87	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
 88	            app.stop();
 89	            Database.close();
 90	        }));
 91	
 92	        System.out.println("Pousada Maré Alta - Sistema de Reservas");
 93	        System.out.println("Servidor rodando na porta " + port);
 94	    }
 95	}
