109	    public static void init(String url, String username, String password) {
110	        HikariConfig config = new HikariConfig();
111	        config.setJdbcUrl(url);
112	        config.setUsername(username);
113	        config.setPassword(password);
114	        config.setMaximumPoolSize(10);
