125	    private static void createTables() {
126	        try (Connection conn = getConnection();
127	             Statement stmt = conn.createStatement()) {
128	
129	            stmt.execute("""
130	                CREATE TABLE IF NOT EXISTS rooms (
131	                    number VARCHAR(10) PRIMARY KEY,
132	                    type VARCHAR(20) NOT NULL,
133	                    capacity INTEGER NOT NULL,
134	                    nightly_rate DECIMAL(10, 2) NOT NULL
135	                )
136	            """);
137	
138	            stmt.execute("""
139	                CREATE TABLE IF NOT EXISTS reservations (
140	                    id BIGSERIAL PRIMARY KEY,
141	                    room_number VARCHAR(10) NOT NULL,
142	                    guest_name VARCHAR(255) NOT NULL,
143	                    guest_email VARCHAR(255) NOT NULL,
144	                    guest_cpf VARCHAR(11) NOT NULL,
145	                    check_in DATE NOT NULL,
146	                    check_out DATE NOT NULL,
147	                    guests INTEGER NOT NULL,
148	                    rate_plan VARCHAR(20) NOT NULL,
149	                    nights INTEGER NOT NULL,
150	                    subtotal DECIMAL(10, 2) NOT NULL,
151	                    discount DECIMAL(10, 2) NOT NULL,
152	                    total DECIMAL(10, 2) NOT NULL,
153	                    status VARCHAR(20) NOT NULL,
154	                    amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
155	                    refund DECIMAL(10, 2),
156	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
157	                )
158	            """);
159	
160	            stmt.execute("""
161	                CREATE TABLE IF NOT EXISTS messages (
162	                    id BIGSERIAL PRIMARY KEY,
163	                    channel VARCHAR(20) NOT NULL,
164	                    recipient VARCHAR(255) NOT NULL,
165	                    subject VARCHAR(500) NOT NULL,
166	                    body TEXT NOT NULL
167	                )
168	            """);
169	
170	            insertRooms(conn);
171	
172	        } catch (SQLException e) {
173	            throw new RuntimeException("Failed to initialize database", e);
174	        }
175	    }
