185	                    ('301', 'SUITE', 4, 579.90)
186	                ON CONFLICT DO NOTHING
187	            """);
188	        }
189	    }
190	
191	    public static void close() {
192	        if (dataSource != null) {
193	            dataSource.close();
194	        }
195	    }
