    31	    public Reservation createReservation(
    32	            String roomNumber,
    33	            String guestName,
    34	            String guestEmail,
    35	            String guestCpf,
    36	            LocalDate checkIn,
    37	            LocalDate checkOut,
    38	            int guests,
    39	            RatePlan ratePlan) {
    40	
    41	        Room room = roomRepository.findByNumber(roomNumber)
    42	            .orElseThrow(() -> new RoomNotFoundException());
    43	
    44	        if (guests > room.getCapacity()) {
    45	            throw new CapacityExceededException();
    46	        }
    47	
    48	        if (reservationRepository.hasConflict(roomNumber, checkIn, checkOut, null)) {
    49	            throw new RoomUnavailableException();
    50	        }
    51	
    52	        Reservation reservation = new Reservation();
    53	        reservation.setRoomNumber(roomNumber);
    54	        reservation.setGuestName(guestName);
    55	        reservation.setGuestEmail(guestEmail);
    56	        reservation.setGuestCpf(guestCpf);
    57	        reservation.setCheckIn(checkIn);
    58	        reservation.setCheckOut(checkOut);
    59	        reservation.setGuests(guests);
    60	        reservation.setRatePlan(ratePlan);
    61	
    62	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    63	        reservation.setNights(nights);
    64	
    65	        BigDecimal subtotal = pricingService.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
    66	        reservation.setSubtotal(subtotal);
    67	
    68	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
    69	        reservation.setDiscount(discount);
    70	
    71	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
    72	        reservation.setTotal(total);
    73	
    74	        reservation.setStatus(ReservationStatus.PENDING);
    75	        reservation.setAmountPaid(BigDecimal.ZERO);
    76	        reservation.setRefund(null);
    77	
    78	        return reservationRepository.save(reservation);
    79	    }
