    92	
    93	        reservation.setStatus(ReservationStatus.CONFIRMED);
    94	        reservation.setAmountPaid(reservation.getTotal());
    95	
    96	        reservationRepository.save(reservation);
    97	
    98	        eventPublisher.publish(new ReservationConfirmedEvent(reservation));
    99	
   100	        return reservation;
