   103	    public Reservation cancelReservation(Long id) {
   104	        Reservation reservation = getReservation(id);
   105	
   106	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN ||
   107	            reservation.getStatus() == ReservationStatus.CHECKED_OUT ||
   108	            reservation.getStatus() == ReservationStatus.CANCELLED) {
   109	            throw new OperationNotAllowedException();
   110	        }
   111	
   112	        ReservationStatus previousStatus = reservation.getStatus();
   113	
   114	        reservation.setStatus(ReservationStatus.CANCELLED);
   115	
   116	        BigDecimal refundAmount = BigDecimal.ZERO;
   117	        if (previousStatus == ReservationStatus.CONFIRMED &&
   118	            reservation.getRatePlan() == RatePlan.STANDARD) {
   119	            refundAmount = reservation.getAmountPaid();
   120	        }
   121	
   122	        reservation.setRefund(refundAmount);
   123	
   124	        reservationRepository.save(reservation);
   125	
   126	        eventPublisher.publish(new ReservationCancelledEvent(reservation, previousStatus));
