    19	        return String.format(BRAZILIAN_LOCALE, "R$ %,.2f", amount);
    20	    }
    21	
    22	    public static String formatCpf(String cpf) {
    23	        if (cpf.length() == 11) {
    24	            return String.format("%s.%s.%s-%s",
    25	                cpf.substring(0, 3),
    26	                cpf.substring(3, 6),
    27	                cpf.substring(6, 9),
    28	                cpf.substring(9, 11)
    29	            );
    30	        }
    31	        return cpf;
    32	    }
