     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.domain.RatePlan;
     4	import com.pousadamarealta.util.MoneyUtil;
     5	
     6	import java.math.BigDecimal;
     7	import java.time.LocalDate;
     8	import java.time.Month;
     9	
    10	public class PricingService {
    11	
    12	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    13	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    14	
    15	    public BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate night) {
    16	        BigDecimal price = baseRate;
    17	
    18	        if (isHighSeason(night)) {
    19	            price = MoneyUtil.round(price.multiply(HIGH_SEASON_MULTIPLIER));
    20	        }
    21	
    22	        return price;
    23	    }
    24	
    25	    public BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
    26	        BigDecimal subtotal = BigDecimal.ZERO;
    27	
    28	        LocalDate current = checkIn;
    29	        while (current.isBefore(checkOut)) {
    30	            BigDecimal nightPrice = calculateNightPrice(baseRate, current);
    31	            subtotal = subtotal.add(nightPrice);
    32	            current = current.plusDays(1);
    33	        }
    34	
    35	        return MoneyUtil.round(subtotal);
    36	    }
    37	
    38	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    39	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    40	            return MoneyUtil.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    41	        }
    42	        return BigDecimal.ZERO;
    43	    }
    44	
    45	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    46	        return MoneyUtil.round(subtotal.subtract(discount));
    47	    }
    48	
    49	    private boolean isHighSeason(LocalDate date) {
    50	        Month month = date.getMonth();
    51	        int day = date.getDayOfMonth();
    52	
    53	        if (month == Month.JULY) {
    54	            return true;
    55	        }
    56	
    57	        if (month == Month.DECEMBER && day >= 15) {
    58	            return true;
    59	        }
    60	
    61	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    62	            return true;
    63	        }
    64	
    65	        return false;
    66	    }
    67	}
