     1	package com.pousadamarealta.event;
     2	
     3	import java.util.ArrayList;
     4	import java.util.HashMap;
     5	import java.util.List;
     6	import java.util.Map;
     7	
     8	public class EventPublisher {
     9	    private final Map<Class<? extends Event>, List<EventListener<? extends Event>>> listeners = new HashMap<>();
    10	
    11	    public <T extends Event> void subscribe(Class<T> eventType, EventListener<T> listener) {
    12	        listeners.computeIfAbsent(eventType, k -> new ArrayList<>()).add(listener);
    13	    }
    14	
    15	    @SuppressWarnings("unchecked")
    16	    public <T extends Event> void publish(T event) {
    17	        List<EventListener<? extends Event>> eventListeners = listeners.get(event.getClass());
    18	        if (eventListeners != null) {
    19	            for (EventListener<? extends Event> listener : eventListeners) {
    20	                ((EventListener<T>) listener).handle(event);
    21	            }
    22	        }
    23	    }
    24	}
