    34	    public static String formatReceipt(Reservation reservation) {
    35	        StringBuilder receipt = new StringBuilder();
    36	        receipt.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
    37	        receipt.append(String.format("Hóspede: %s (CPF %s)\n",
    38	            reservation.getGuestName(),
    39	            formatCpf(reservation.getGuestCpf())));
    40	        receipt.append(String.format("Quarto: %s (%s)\n",
    41	            reservation.getRoomNumber(),
    42	            getRoomType(reservation.getRoomNumber())));
    43	        receipt.append(String.format("Entrada: %s | Saída: %s | %d %s\n",
    44	            formatDate(reservation.getCheckIn()),
    45	            formatDate(reservation.getCheckOut()),
    46	            reservation.getNights(),
    47	            reservation.getNights() == 1 ? "diária" : "diárias"));
    48	        receipt.append(String.format("Diárias: %s\n", formatMoney(reservation.getSubtotal())));
    49	
    50	        if (reservation.getDiscount() != null && reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    51	            receipt.append(String.format("Desconto: %s\n", formatMoney(reservation.getDiscount())));
    52	        }
    53	
    54	        receipt.append(String.format("Total: %s", formatMoney(reservation.getTotal())));
    55	
    56	        return receipt.toString();
    57	    }
    58	
    59	    private static String getRoomType(String roomNumber) {
    60	        if (roomNumber.startsWith("1")) return "STANDARD";
    61	        if (roomNumber.startsWith("2")) return "DELUXE";
    62	        return "SUITE";
    63	    }
    64	}
